"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  Calendar as CalendarIcon, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  GraduationCap, 
  Heart, 
  AlertOctagon, 
  Info, 
  CheckCircle2, 
  X, 
  Clock, 
  UploadCloud 
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [
  { date: "2026-01-26", name: "Republic Day" },
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-50" },
  { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-50", requiresDoc: true },
  { id: "casual", label: "Casual", icon: Briefcase, balance: 6, color: "text-amber-600", bg: "bg-amber-50" },
  { id: "comp_off", label: "Comp Off", icon: Umbrella, balance: 3, color: "text-emerald-600", bg: "bg-emerald-50" },
  { id: "maternity", label: "Maternity", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-50", requiresDoc: true },
  { id: "bereavement", label: "Bereavement", icon: Heart, balance: 5, color: "text-slate-600", bg: "bg-slate-100" },
  { id: "study", label: "Study", icon: GraduationCap, balance: 0, color: "text-indigo-600", bg: "bg-indigo-50" },
  { id: "unpaid", label: "L.O.P", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-50" },
];

export default function OneScreenAbsence() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [typeId, setTypeId] = useState("annual");
  const [halfDay, setHalfDay] = useState<"am" | "pm" | null>(null);
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
      setHalfDay(null);
    } else {
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dateStr, end: "" });
      } else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  const stats = useMemo(() => {
    if (!range.start || !range.end) return { days: 0, deduction: 0 };
    let d = 0, deduction = 0;
    let cur = new Date(range.start);
    let end = new Date(range.end);
    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const isHoliday = HOLIDAYS.some(h => h.date === dateStr);
      const isWeekend = cur.getDay() === 0 || cur.getDay() === 6;
      
      if (!isHoliday && !isWeekend) {
        deduction += (range.start === range.end && halfDay) ? 0.5 : 1;
      }
      d++;
      cur.setDate(cur.getDate() + 1);
    }
    return { days: d, deduction };
  }, [range, halfDay]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;

  return (
    <div className="flex h-screen w-full flex-col bg-white text-slate-800 overflow-hidden font-sans">
      
      {/* 1. COMPACT HEADER (Fixed Height: 60px) */}
      <header className="flex h-[60px] items-center justify-between border-b px-6">
        <div className="flex items-center gap-2">
          <div className="rounded-lg bg-slate-900 p-1.5 text-white"><CalendarIcon className="h-4 w-4" /></div>
          <span className="font-bold text-slate-900">Request Absence<span className="text-slate-400"></span></span>
        </div>
        <div className="flex items-center gap-4 text-xs font-medium text-slate-500">
           <span>Hyderabad Office</span>
           <div className="h-4 w-px bg-slate-200"></div>
           <span className="flex items-center gap-2">
             <span className="h-2 w-2 rounded-full bg-emerald-500"></span> Balance: {selectedType.balance} Days
           </span>
        </div>
      </header>

      {/* 2. MAIN GRID (Fills remaining height) */}
      <div className="flex flex-1 overflow-hidden">
        
        {/* LEFT: LEAVE TYPES (Slim Sidebar) */}
        <nav className="w-[240px] flex-none border-r bg-slate-50/50 flex flex-col overflow-y-auto">
           <div className="p-4 text-[10px] font-bold uppercase tracking-widest text-slate-400">Leave Type</div>
           <div className="space-y-1 px-3 pb-3">
              {LEAVE_TYPES.map((t) => (
                <button
                  key={t.id}
                  onClick={() => setTypeId(t.id)}
                  className={`flex w-full items-center gap-3 rounded-xl p-3 text-left transition-all ${
                    typeId === t.id ? "bg-white shadow-sm ring-1 ring-slate-200" : "hover:bg-slate-100"
                  }`}
                >
                  <div className={`rounded-lg p-2 ${t.bg} ${t.color}`}><t.icon className="h-4 w-4" /></div>
                  <div>
                    <div className={`text-xs font-bold ${typeId === t.id ? "text-slate-900" : "text-slate-500"}`}>{t.label}</div>
                    <div className="text-[10px] text-slate-400">{t.balance} Days</div>
                  </div>
                </button>
              ))}
           </div>
        </nav>

        {/* CENTER: CALENDAR (Flexible Width) */}
        <main className="flex-1 flex flex-col bg-white relative">
          
          {/* Calendar Toolbar */}
          <div className="flex h-[60px] flex-none items-center justify-between border-b px-6">
             <h2 className="text-lg font-bold">January 2026</h2>
             
             {/* THE MODE SWITCHER */}
             <div className="flex bg-slate-100 p-1 rounded-lg">
                <button 
                  onClick={() => { setMode("single"); setRange({start:"", end:""}); }}
                  className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${mode === "single" ? "bg-white text-blue-600 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Single Day
                </button>
                <button 
                  onClick={() => { setMode("range"); setRange({start:"", end:""}); }}
                  className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${mode === "range" ? "bg-white text-blue-600 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Date Range
                </button>
             </div>
          </div>

          {/* Calendar Grid - SCROLLS INTERNALLY IF NEEDED, BUT FITS SCREEN */}
          <div className="flex-1 p-6 overflow-y-auto">
             <div className="grid grid-cols-7 gap-2 h-full content-start">
                {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                  <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase mb-2">{d}</div>
                ))}
                
                {/* Jan 1 is Thursday */}
                {[null, null, null].map((_, i) => <div key={`e-${i}`} />)}

                {Array.from({ length: 31 }).map((_, i) => {
                  const day = i + 1;
                  const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                  const holiday = HOLIDAYS.find(h => h.date === dateStr);
                  const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;
                  
                  const isSelected = range.start === dateStr || range.end === dateStr;
                  const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                  return (
                    <button
                      key={day}
                      onClick={() => handleDateClick(dateStr)}
                      disabled={isWeekend && !holiday} // Optional: Disable weekends if needed
                      className={`
                        relative h-24 rounded-xl border text-left p-2 transition-all group
                        ${isSelected ? "bg-slate-900 text-white border-slate-900 shadow-lg scale-[1.02] z-10" : ""}
                        ${inRange ? "bg-blue-50 text-blue-700 border-blue-100" : ""}
                        ${holiday && !inRange && !isSelected ? "bg-rose-50 border-rose-100" : ""}
                        ${isWeekend && !inRange && !isSelected ? "bg-slate-50 border-slate-50 text-slate-300" : "bg-white border-slate-100 hover:border-blue-400"}
                      `}
                    >
                      <span className="text-sm font-bold">{day}</span>
                      
                      {holiday && (
                         <span className={`absolute bottom-2 left-2 right-2 text-[9px] font-bold truncate px-1.5 py-0.5 rounded ${isSelected ? "bg-white/20 text-white" : "bg-rose-100 text-rose-600"}`}>
                            {holiday.name}
                         </span>
                      )}
                      
                      {isSelected && (
                         <span className="absolute top-2 right-2">
                            <CheckCircle2 className="h-4 w-4 text-white" />
                         </span>
                      )}
                    </button>
                  );
                })}
             </div>
          </div>
        </main>

        {/* RIGHT: ACTION PANEL (Fixed Width: 320px) */}
        <aside className="w-[320px] flex-none border-l bg-white flex flex-col shadow-xl z-20">
           
           {/* Section 1: Summary */}
           <div className="p-6 border-b bg-slate-50/50">
              <h3 className="text-xs font-bold uppercase text-slate-400 mb-4">Request Summary</h3>
              <div className="bg-white rounded-xl border p-4 shadow-sm space-y-3">
                 <div className="flex justify-between items-center">
                    <span className="text-xs text-slate-500">Leave Type</span>
                    <span className="text-xs font-bold">{selectedType.label}</span>
                 </div>
                 <div className="flex justify-between items-center">
                    <span className="text-xs text-slate-500">Dates</span>
                    <span className="text-xs font-bold">{range.start ? `${range.start.slice(5)}` : "-"} {range.end ? `to ${range.end.slice(5)}` : ""}</span>
                 </div>
                 <div className="h-px bg-slate-100 my-2"></div>
                 <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-slate-700">Net Deduction</span>
                    <span className="text-xl font-black text-blue-600">{stats.deduction} Days</span>
                 </div>
              </div>
           </div>

           {/* Section 2: Inputs */}
           <div className="flex-1 p-6 space-y-5 overflow-y-auto">
              
              {/* Half Day Toggle */}
              {mode === "single" && range.start && (
                <div>
                   <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Duration</label>
                   <div className="grid grid-cols-3 gap-2 bg-slate-100 p-1 rounded-lg">
                      <button onClick={() => setHalfDay(null)} className={`text-[10px] font-bold py-2 rounded ${!halfDay ? "bg-white shadow text-slate-900" : "text-slate-400"}`}>Full</button>
                      <button onClick={() => setHalfDay("am")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "am" ? "bg-white shadow text-slate-900" : "text-slate-400"}`}>AM</button>
                      <button onClick={() => setHalfDay("pm")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "pm" ? "bg-white shadow text-slate-900" : "text-slate-400"}`}>PM</button>
                   </div>
                </div>
              )}

              {/* Reason */}
              <div>
                 <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Reason</label>
                 <textarea 
                   className="w-full h-24 rounded-xl border border-slate-200 p-3 text-xs font-medium focus:ring-2 focus:ring-slate-900 outline-none resize-none"
                   placeholder="Brief reason for absence..."
                   value={reason}
                   onChange={(e) => setReason(e.target.value)}
                 />
              </div>

              {/* File Upload */}
              {selectedType.requiresDoc && (
                 <div>
                    <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block flex justify-between">
                       <span>Attachment</span> <span className="text-rose-500">* Required</span>
                    </label>
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="border-2 border-dashed border-slate-200 rounded-xl h-20 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-50 hover:border-slate-300 transition-colors"
                    >
                       <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                       {file ? (
                          <span className="text-xs font-bold text-emerald-600 flex items-center gap-1"><CheckCircle2 className="h-3 w-3"/> Attached</span>
                       ) : (
                          <div className="flex flex-col items-center text-slate-400">
                             <UploadCloud className="h-4 w-4 mb-1" />
                             <span className="text-[9px] font-bold">Upload Proof</span>
                          </div>
                       )}
                    </div>
                 </div>
              )}
           </div>

           {/* Section 3: Submit */}
           <div className="p-6 border-t bg-slate-50">
              <button 
                disabled={!range.start || (selectedType.requiresDoc && !file)}
                className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold text-sm shadow-lg hover:bg-black disabled:bg-slate-300 transition-all flex items-center justify-center gap-2"
              >
                 {range.start ? "Submit Request" : "Select Dates"}
              </button>
           </div>
        </aside>

      </div>
    </div>
  );
}